  internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();ExtBrowserWindow window=null;MainWindow main=null;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);checks.Add(label);};Action<Action,string> reject=(run,label)=>{bool failed=false;try{run();}catch{failed=true;}check(failed,label);};try{
   string path=Expand("minimal.ext2.gz",root,"sample.ext2");string before=FileParts.Hash(path,CancellationToken.None);var source=ExtDiskStream.Image(path);var volumes=ExtReader.Scan(source);check(volumes.Length==1&&volumes[0].Error==null,"Native ext2 volume detected");var request=new ExtRequest{Source=source,Volume=volumes[0],Action="list",Path="/"};var result=ExtReader.Run(request);check(result.Entries.Any(x=>x.Name=="hello.txt"&&x.Readable)&&result.Entries.Any(x=>x.Name=="Documents"&&x.Directory),"Root file and directory listing");check(result.Entries.Any(x=>x.Name=="device"&&!x.Readable),"Special devices are not exported");check(result.Entries.Any(x=>x.Name=="link"&&!x.Readable),"Symbolic links are not followed by copy");check(result.Entries.Any(x=>x.Name=="CASE.txt")&&result.Entries.Any(x=>x.Name=="case.txt"),"Case-sensitive names remain distinct");request.Path="/Documents";result=ExtReader.Run(request);check(result.Entries.Single().Name=="Čeština.txt","UTF-8 filenames preserved");
