   request.Action="preview";request.Path="/large-sparse.bin";request.Target=Path.Combine(root,"large-preview.bin");reject(()=>ExtReader.Run(request),"Preview refuses files above 64 MiB before reading");request.Path="/hello.txt";request.Target=Path.Combine(root,"preview.txt");result=ExtReader.Call(request,CancellationToken.None);check(File.ReadAllText(request.Target)=="hello from ext2\n","Isolated worker reads exact file contents");request.Action="list";request.Path="/";result=ExtReader.Call(request,CancellationToken.None);check(result.Entries.Length>=6,"Isolated directory listing worker");check(FileParts.Hash(path,CancellationToken.None)==before,"Source image bytes unchanged after listing, export and preview");
   foreach(string fixture in new[]{"mbr.ext2.gz","gpt512.ext2.gz","gpt4096.ext2.gz"}){string image=Expand(fixture,root,fixture+".img");var item=ExtDiskStream.Image(image);var scan=ExtReader.Scan(item);check(scan.Length==1&&scan[0].Offset==1024*1024&&scan[0].Error==null,"Linux partition discovered: "+fixture);var listing=ExtReader.Run(new ExtRequest{Action="list",Source=item,Volume=scan[0],Path="/Documents"});check(listing.Entries.Length==1,"Partition contents read: "+fixture);}
   string ext4=Expand("data.ext4.dat.gz",root,"sample.ext4");var extSource=ExtDiskStream.Image(ext4);var extVolumes=ExtReader.Scan(extSource);check(extVolumes.Length==1&&extVolumes[0].Error==null,"Upstream real ext4 fixture detected");using(var session=new ExtReader.Session(new ExtRequest{Source=extSource,Volume=extVolumes[0]})){check(!session.FileSystem.CanWrite,"Library is read-only");using(var file=session.FileSystem.OpenFile("bar/blah.txt",FileMode.Open,FileAccess.Read))using(var reader=new StreamReader(file))check(reader.ReadToEnd()=="hello world\n","Ext4 extent-backed file read");}
   byte[] bad=File.ReadAllBytes(path);bad[1024+96]|=4;string dirty=Path.Combine(root,"dirty.ext4");File.WriteAllBytes(dirty,bad);check(ExtReader.Scan(ExtDiskStream.Image(dirty)).Single().Error.Contains(L.Text("ext.dirty")),"Journal recovery required is refused without repair");bad=File.ReadAllBytes(path);bad[1024+98]|=1;string encrypted=Path.Combine(root,"encrypted.ext4");File.WriteAllBytes(encrypted,bad);check(ExtReader.Scan(ExtDiskStream.Image(encrypted)).Single().Error!=null,"Unsupported incompatibility features rejected");
   check(UsbDriveActions.Eligible(new ExtSource{Physical=true,Removable=true},3,0,1),"Confirmed removable USB disk is eligible");check(!UsbDriveActions.Eligible(new ExtSource{Physical=true,Removable=false},3,0,1),"Fixed USB disks do not get flash-only destructive commands");check(!UsbDriveActions.Eligible(new ExtSource{Physical=true,Removable=true},0,0,1),"Windows system disk excluded");check(!UsbDriveActions.Eligible(new ExtSource{Physical=true,Removable=true},1,0,1),"Application disk excluded");
   System.Threading.SynchronizationContext.SetSynchronizationContext(new System.Windows.Threading.DispatcherSynchronizationContext(System.Windows.Threading.Dispatcher.CurrentDispatcher));FluentTheme.Ensure();window=new ExtBrowserWindow(null){Left=-18000,Top=-18000,WindowStartupLocation=WindowStartupLocation.Manual,ShowActivated=false};window.Show();NavigationTests.Wait(window.Pending);window.Sources.ItemsSource=new[]{source};window.Sources.SelectedIndex=0;NavigationTests.Wait(window.Pending);window.UpdateLayout();check(window.Files.Items.Count>=6&&window.Address.Text=="/","Native browser lists selected filesystem");check(window.Files.IsReadOnly&&!window.Files.CanUserDeleteRows,"Native browser exposes no source edit/delete action");NavigationTests.Wait(window.Navigate("/Documents"));check(window.Files.Items.Cast<ExtEntry>().Any(x=>x.Name=="Čeština.txt")&&window.Files.Items.Cast<ExtEntry>().Any(x=>x.Parent),"Native folder navigation and parent row");NextStageTests.Draw(window,Path.Combine(root,"ext-browser.png"));window.Width=800;window.Height=540;window.UpdateLayout();check(window.Copy.ActualWidth>0&&window.Preview.ActualWidth>0,"Action buttons remain visible in compact window");check(HelpContent.ContextTopic(typeof(ExtBrowserWindow))=="ext","Contextual F1 topic for Linux disks");window.Sources.ItemsSource=new[]{ExtDiskStream.Image(dirty)};window.Sources.SelectedIndex=0;NavigationTests.Wait(window.Pending);window.UpdateLayout();check(window.Files.Items.Count==0&&window.EmptyState.IsVisible&&window.EmptyState.Text.Contains(L.Text("ext.dirty")),"Dirty EXT error appears inside empty file area instead of looking like an empty disk");window.Close();window=null;
   main=new MainWindow(root,new ProgramSettings{AutoRefresh=false}){Left=-18000,Top=-18000,ShowInTaskbar=false,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual};main.Show();NavigationTests.WaitPanels(main);main.OpenExtVolume(source,volumes[0],true);NavigationTests.WaitPanels(main);var panel=FluentUiTests.Children<FilePanel>(main).Single(x=>x.IsExt);NavigationTests.Wait(panel.NavigationTask);check(panel.IsVirtualBrowser&&panel.List.Items.Cast<Entry>().Any(x=>x.FullPath.EndsWith("/hello.txt")),"EXT partition opens inside the regular right file panel as read-only virtual source");var location=ExtLocations.Get(panel.CurrentPath);panel.Navigate(location.Root+"Documents",true);NavigationTests.Wait(panel.NavigationTask);check(panel.List.Items.Cast<Entry>().Any(x=>x.IsParent)&&panel.List.Items.Count==2,"EXT panel navigates folders with a parent row");panel.Up();NavigationTests.Wait(panel.NavigationTask);check(panel.CurrentPath==location.Root,"EXT panel parent returns to the partition root");var saved=panel.SaveTabs();check(saved.Any(x=>x.ExtSource!=null&&x.ExtVolume!=null),"EXT tab preserves its source and partition identity");var entry=panel.List.Items.Cast<Entry>().Single(x=>x.FullPath.EndsWith("/hello.txt"));panel.SelectContextEntry(entry);var menu=panel.List.ContextMenu;menu.RaiseEvent(new RoutedEventArgs(ContextMenu.OpenedEvent));foreach(string command in new[]{"action.edit","action.move","action.rename","action.delete","action.paste"})check(!menu.Items.OfType<MenuItem>().Single(x=>Convert.ToString(x.Tag)==command).IsEnabled,"EXT read-only context disables "+command);panel.ViewSelected();var quick=(QuickPreviewPane)typeof(MainWindow).GetField("quickPreview",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(main);NavigationTests.Wait(quick.LoadingTask);File.WriteAllLines(Path.Combine(root,"preview-state.txt"),FluentUiTests.Children<TextBlock>(quick).Select(x=>x.Text).Concat(new[]{"TEMP: "+quick.PreviewTempPath}));check(quick.PreviewTempPath!=null&&File.ReadAllText(Path.Combine(quick.PreviewTempPath,"hello.txt"))=="hello from ext2\n","EXT F3 prepares exact file bytes inside the opposite-panel preview");main.CloseQuickPreview();string panelExport=Path.Combine(root,"panel-export");NavigationTests.Wait(panel.ExportExt(new[]{entry.FullPath},panelExport,CancellationToken.None));check(File.ReadAllText(Path.Combine(panelExport,"hello.txt"))=="hello from ext2\n","EXT panel export preserves file bytes");NavigationTests.Wait(panel.ReleaseUsbRoots(new[]{@"H:\"},root,source));check(!panel.IsExt&&panel.CurrentPath==root,"Safe removal releases an EXT panel by physical-source identity rather than drive-letter path");main.OpenExtVolume(source,volumes[0],false);NavigationTests.WaitPanels(main);var leftOrigin=main.ExtOriginPanel;window=new ExtBrowserWindow(main){Left=-18000,Top=-18000,ShowActivated=false,ShowInTaskbar=false,WindowStartupLocation=WindowStartupLocation.Manual};window.Show();NavigationTests.Wait(window.Pending);check(!FluentUiTests.Children<Button>(main).Any(x=>Convert.ToString(x.Content)=="EXT"),"Drive bars have no EXT launcher button");var diskMenu=FluentUiTests.Children<MenuItem>(main).First(x=>Convert.ToString(x.Header)==L.Text("analyzer.menuGroup"));check(diskMenu.Items.OfType<MenuItem>().Any(x=>Convert.ToString(x.Header)==L.Text("ext.title")),"Linux disks is inside Disk tools");window.Sources.ItemsSource=new[]{source};window.Sources.SelectedIndex=0;NavigationTests.Wait(window.Pending);check(FluentUiTests.Children<Button>(window).Count(x=>Convert.ToString(x.Content)==L.Text("ext.openLeft")||Convert.ToString(x.Content)==L.Text("ext.openRight"))==2,"Linux reader offers explicit left and right panel buttons");check(window.Files.Items.Count>=6,"Selecting a source automatically reads its partitions and files");main.OpenExtVolume(source,volumes[0],true);NavigationTests.WaitPanels(main);window.OpenInPanel(false);window=null;NavigationTests.WaitPanels(main);check(main.ExtOriginPanel==leftOrigin&&leftOrigin.IsExt,"Open left uses the selected destination even after focus changes");panel.Navigate(root,true);NavigationTests.Wait(panel.NavigationTask);check(!panel.IsExt&&!panel.IsVirtualBrowser,"Selecting a local folder exits EXT panel context");check(FileParts.Hash(path,CancellationToken.None)==before,"Panel browsing, F3 and export leave source image unchanged");main.Close();main=null;
   File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count}));return 0;
  }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"FAIL: "+ex}));return 1;}finally{if(window!=null)window.Close();if(main!=null)main.Close();}}
